        CaptionLine(
          start: Duration(milliseconds: 466843),
          end: Duration(milliseconds: 470843),
          text:
              'Their responsibility had been to speak truthfully when it mattered.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 470843),
          end: Duration(milliseconds: 475843),
          text:
              'What happened afterwards belonged to the people responsible for dealing with the matter.',
