          text: 'Akhlaq repeated it slowly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 530927),
          end: Duration(milliseconds: 532427),
          text: '“Siddiq.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 532427),
          end: Duration(milliseconds: 537367),
          text: '“A person deeply committed to truth,” Sheikh Uncle explained.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 537367),
          end: Duration(milliseconds: 541715),
          text: '“And Allah tells us that Idris was a Prophet.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 542515),
          end: Duration(milliseconds: 543715),
          text: 'Imaan waited.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 543715),
          end: Duration(milliseconds: 545715),
