          text: 'Imaan looked thoughtful.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 584451),
          end: Duration(milliseconds: 588211),
          text: '“So perhaps the quality is part of the story.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 588211),
