          end: Duration(milliseconds: 909764),
          text: 'Level-Up',
        ),
        CaptionLine(
          start: Duration(milliseconds: 909764),
          end: Duration(milliseconds: 916264),
          text:
              'If someone irritates, excludes or disappoints you today, wait before responding.',
